mapper.select:
select device_sn
from member_device_info
where deleted = 0
  AND type = #{type}
  AND room_id is null
  AND store_id = #{storeId}

select device_sn
from member_device_info
where deleted = 0
  AND type = #{type}
  AND room_id = #{roomId}

select d.*, s.store_name, r.room_name
from member_device_info d
left join member_store_info s ON s.store_id = d.store_id
left join member_room_info r ON r.room_id = d.room_id
where d.deleted = 0

    and locate(#{deviceSn},d.device_sn)>0


    and d.type=#{type}


    and d.status=#{status}


    and d.room_id=#{roomId}


    and d.store_id=#{storeId}


    and d.create_time between

        #{dateTime}


order by d.store_id,d.room_id
